// Regenerates mobile/src/lib/bundled-packs.ts from public/packs/{lang}/{level}.json.
// Run after adding a language or level: node scripts/generate-mobile-packs.mjs
import { readdir, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const packsDirectory = path.join(root, "public", "packs");
const lines = [
  "/* Generated by scripts/generate-mobile-packs.mjs – do not edit by hand. */",
  "// All public packs are bundled into the native app, so learning works fully offline from the first start.",
  "export const BUNDLED_PACKS: Record<string, () => unknown> = {",
];
const languages = (await readdir(packsDirectory, { withFileTypes: true })).filter((entry) => entry.isDirectory()).map((entry) => entry.name).sort();
for (const language of languages) {
  const files = (await readdir(path.join(packsDirectory, language))).filter((file) => file.endsWith(".json")).sort();
  for (const file of files) {
    lines.push(`  "${language.toUpperCase()}:${path.basename(file, ".json").toUpperCase()}": () => require("../../../public/packs/${language}/${file}"),`);
  }
}
lines.push("};");
await writeFile(path.join(root, "mobile", "src", "lib", "bundled-packs.ts"), `${lines.join("\n")}\n`);
console.log(`bundled-packs.ts aktualisiert (${lines.length - 4} Packs).`);
